const sha256 = e => {
    const t = e.length,
        r = new Uint32Array(16 * (t + 9 + 63 >> 6));
    for (let s = 0; s < t; s++) r[s >> 2] |= e[s] << 24 - 8 * (3 & s);
    r[t >> 2] |= 128 << 24 - 8 * (3 & t), r[r.length - 2] = Math.floor(t / 536870912), r[r.length - 1] = t << 3;
    const s = Uint32Array.of(1779033703, 3144134277, 1013904242, 2773480762, 1359893119, 2600822924, 528734635, 1541459225),
        n = new Uint32Array(64);
    for (let e = 0; e < r.length; e += 16) {
        for (let t = 0; t < 16; t++) n[t] = r[e + t];
        for (let e = 16; e < 64; e++) {
            const t = n[e - 15],
                r = n[e - 2];
            n[e] = n[e - 16] + ((t >>> 7 | t << 25) ^ (t >>> 18 | t << 14) ^ t >>> 3) + n[e - 7] + ((r >>> 17 | r << 15) ^ (r >>> 19 | r << 13) ^ r >>> 10)
        }
        let t = s[0],
            i = s[1],
            a = s[2],
            o = s[3],
            l = s[4],
            c = s[5],
            h = s[6],
            p = s[7];
        for (let e = 0; e < 64; e++) {
            const r = p + ((l >>> 6 | l << 26) ^ (l >>> 11 | l << 21) ^ (l >>> 25 | l << 7)) + (l & c ^ ~l & h) + SHA_K[e] + n[e] | 0,
                s = ((t >>> 2 | t << 30) ^ (t >>> 13 | t << 19) ^ (t >>> 22 | t << 10)) + (t & i ^ t & a ^ i & a) | 0;
            p = h, h = c, c = l, l = o + r | 0, o = a, a = i, i = t, t = r + s | 0
        }
        s[0] += t, s[1] += i, s[2] += a, s[3] += o, s[4] += l, s[5] += c, s[6] += h, s[7] += p
    }
    const i = new Uint8Array(32);
    for (let e = 0; e < 32; e++) i[e] = s[e >> 2] >>> 24 - 8 * (3 & e) & 255;
    return i
};

