function _tcHash(str) {
  str = String(str || "");
  var h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (var i = 0, ch; i < str.length; i++) {
    ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36) + "x" + str.length.toString(36);
}

function _tcRemoteEnabled(ext) {
  try { return String((ext && ext.getPreference(TC_REMOTE_SYNC_KEY)) || "") !== "off"; } catch (e) { return true; }
}

function _tcRemoteUrl(ext) {
  try {
    var v = String((ext && ext.getPreference(TC_REMOTE_URL_KEY)) || "").trim();
    return v || TC_REMOTE_DEFAULT_URL;
  } catch (e) {
    return TC_REMOTE_DEFAULT_URL;
  }
}

function _tcRemoteToken(ext) {
  try {
    return String((ext && ext.getPreference(TC_REMOTE_TOKEN_KEY)) || "").trim();
  } catch (e) {
    return "";
  }
}

function _tcRemoteHeaders(ext) {
  var h = {
    "Content-Type": "application/json",
    "Accept": "application/json",
    "User-Agent": USER_AGENT
  };
  var tok = _tcRemoteToken(ext);
  if (tok) h["Authorization"] = "Bearer " + tok;
  return h;
}

async function _tcRemoteLoad(ext, h, n) {
  try {
    if (!_tcRemoteEnabled(ext) || !ext || !h || !n) return null;
    var base = _tcRemoteUrl(ext);
    if (!base) return null;
    var sep = base.indexOf("?") >= 0 ? "&" : "?";
    var res = await ext.client.get(base + sep + "h=" + encodeURIComponent(h), _tcRemoteHeaders(ext));
    if (!res || res.statusCode < 200 || res.statusCode >= 300 || !res.body) return null;
    var parsed = JSON.parse(String(res.body));
    var arr = Array.isArray(parsed) ? parsed : (Array.isArray(parsed && parsed.arr) ? parsed.arr : null);
    if (!arr || arr.length !== n) return null;
    return arr;
  } catch (e) {
    return null;
  }
}

async function _tcRemoteSave(ext, h, name, n, arr) {
  try {
    if (!_tcRemoteEnabled(ext) || !ext || !h || !n || !Array.isArray(arr) || arr.length !== n) return;
    var done = 0;
    for (var i = 0; i < arr.length; i++) if (arr[i]) done++;
    if (!done || _tcRemoteSentAt[h] === done) return;
    var base = _tcRemoteUrl(ext);
    if (!base) return;
    var payload = { h: h, name: String(name || "").slice(0, 60), total: n, done: done, arr: arr };
    var res = await ext.client.post(base, _tcRemoteHeaders(ext), payload);
    if (res && res.statusCode >= 200 && res.statusCode < 300) {
      _tcRemoteSentAt[h] = done;
    }
  } catch (e) {
    /* 원격 저장 실패는 재생과 번역에 영향을 주지 않음 */
  }
}

