        const t = /^(?:https?:\/\/(?:www\.)?hentai\.tv)?\/hentai\/([a-z0-9-]+)\/?(?:[?#]|$)/.exec(String(e || ""));
        if (!t) throw new Error("hentai.tv 회차 주소가 아닙니다.");
        return t[1]
